-- Fixed public presentation preconditions only. SELECTs return counts/validation/hash, never image bodies or customer/account data.
-- Each statement is an independent observation; refresh before any separately approved release.

-- display
with expected(slot) as (select unnest(array['card-services','listing-wifi','listing-parking','listing-furnished','listing-ensuite','listing-bills','listing-security','listing-custom','listing-water','listing-electricity'])) select jsonb_build_object('observed_at',now(),'expected',10,'present',(select count(*) from public.listing_display_options d join expected e using(slot)),'missing',(select coalesce(jsonb_agg(e.slot order by e.slot),'[]'::jsonb) from expected e left join public.listing_display_options d using(slot) where d.slot is null),'enabled',(select count(*) from public.listing_display_options d join expected e using(slot) where d.enabled),'disabled',(select count(*) from public.listing_display_options d join expected e using(slot) where not d.enabled),'null_values',(select count(*) from public.listing_display_options d join expected e using(slot) where d.enabled is null),'additional_slots',(select count(*) from public.listing_display_options d where not exists(select 1 from expected e where e.slot=d.slot))) as display_preconditions;

-- icons
with compiled(slot) as (select unnest(array['find','saved','inbox','you','sun','moon','location-arrow','location-pin','tools','card-grid','list-view','flag','chevron','info','arrow-right','arrow-ne','eye','eye-off','water','bolt','shield','wifi','smoking','pets','furnished','bed','shower','bills','parking','bbq','pool','key-card','duplicate','balcony','shop','house','building','pause','pencil'])), shape as (
 select s.slot,s.label,s.listing_kind,o.source_slot,o.path_d,
  exists(select 1 from compiled c where c.slot=s.slot) as compiled_slot,
  case when o.source_slot is null then true else exists(select 1 from public.site_icon_slots b join compiled c on c.slot=b.slot where b.slot=o.source_slot and b.listing_kind is null) end as valid_source,
  case when o.path_d is null then true else length(o.path_d) between 3 and 1200 and o.path_d ~ '^[MmLlHhVvCcSsQqTtAaZz0-9 .,+-]+$' end as valid_path
 from public.site_icon_slots s left join public.site_icon_overrides o using(slot))
select jsonb_build_object('observed_at',now(),'slots',(select count(*) from shape),'compiled_sprite_slots',39,'within_catalogue_cap',(select count(*)<=128 from shape),'overrides',(select count(*) from public.site_icon_overrides),'orphan_overrides',(select count(*) from public.site_icon_overrides o where not exists(select 1 from public.site_icon_slots s where s.slot=o.slot)),'invalid_sources',(select count(*) from shape where not valid_source),'invalid_paths',(select count(*) from shape where not valid_path),'ambiguous_artwork',(select count(*) from shape where source_slot is not null and path_d is not null),'missing_custom_artwork',(select count(*) from shape where not compiled_slot and source_slot is null and path_d is null),'invalid_catalogue_kinds',(select count(*) from shape where listing_kind is not null and listing_kind not in ('amenity','utility')),'invalid_catalogue_labels',(select count(*) from shape where listing_kind is not null and length(trim(label)) not between 2 and 60),'duplicate_catalogue_labels',(select count(*) from (select lower(trim(label)) from shape where listing_kind is not null group by lower(trim(label)) having count(*)>1) x),'aliased_sources_with_overrides',(select count(*) from shape a where source_slot is not null and exists(select 1 from public.site_icon_overrides b where b.slot=a.source_slot)),'legacy_history_rows',(select count(*) from public.site_icon_revisions)) as icon_preconditions;

-- favicon
with singleton as (select id,png,previous_png,revision from public.site_favicon), assets as (
 select 'current'::text as label,png as value,revision from singleton where id union all select 'previous',previous_png,revision from singleton where id), raw as (
 select *,case when value is not null and length(value)<=40000 and value ~ '^data:image/png;base64,([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$' then decode(substr(value,23),'base64') else null end as bytes from assets)
select jsonb_build_object('observed_at',now(),'rows',(select count(*) from singleton),'true_singletons',(select count(*) from singleton where id),'assets',(select coalesce(jsonb_agg(jsonb_build_object('asset',label,'required_for_adoption',label='current' or revision>0,'revision',revision,'present',value is not null,'source_validator_accepts',value is null or (bytes is not null and length(bytes)>=32 and encode(substring(bytes from 1 for 8),'hex')='89504e470d0a1a0a' and encode(substring(bytes from 13 for 12),'hex')='494844520000004000000040'),'decoded_bytes',length(bytes),'sha256',case when bytes is not null then encode(sha256(bytes),'hex') else null end) order by label),'[]'::jsonb) from raw)) as favicon_preconditions;
